export function resolveDishImage(dish) {
  if (!dish) return '';
  if (dish.slug && SLUG_IMAGE_MAP[dish.slug]) {
    return SLUG_IMAGE_MAP[dish.slug];
  }
  return dish.gambar || '';
}
